const getJourney=id=>launchJourneys.find(j=>j.id===id)||launchJourneys[0];
const card=(kind,label,item,j,number)=>{const available=Boolean(item);return `<button class="launch-system ${kind} ${available?'':'unavailable'}" data-launch-stage="${kind}" data-url="${available?e(item[1]):''}" data-label="${available?e(item[0]):''}" data-journey="${e(j.id)}" ${available?'':'disabled'}><span class="launch-step">${number}</span><span class="launch-system-copy"><small>${e(label)}</small><strong>${available?e(item[0]):kind==='external'?'Not an External ID journey':'Not used in this journey'}</strong></span><span class="launch-arrow">↗</span></button>`;};
